'use strict';

// Converts the shared Claude Code agents (agents/*.md) into the agent formats of
// omp (.omp/agents/<name>.md) and OpenCode (.opencode/agents/<name>.md). The body
// is copied unchanged; only the frontmatter is rewritten per CLI. Installed by
// `--with-omp` / `--with-opencode` (lib/scaffold.js).

// The fixed prefix of the comment line every generated file carries. scaffold
// uses it to tell a generated file (refreshed, or deleted when its source is
// gone) from a downstream's own file of the same name (never touched).
const GENERATED_MARKER = '# Generated by agent-workflow-beads from agents/';

// Claude Code tool name -> omp `tools` names. omp's `read` also fetches URLs, so
// WebFetch adds nothing.
const OMP_TOOLS = {
  Read: ['read'],
  Grep: ['grep'],
  Glob: ['glob'],
  Bash: ['bash'],
  Edit: ['edit'],
  Write: ['write'],
  WebFetch: [],
};

// Claude Code tool name -> OpenCode `permission` keys (allowed). OpenCode's
// `edit` permission covers write and patch.
const OPENCODE_PERMISSIONS = {
  Read: ['read'],
  Grep: ['grep'],
  Glob: ['glob'],
  Bash: ['bash'],
  Edit: ['edit'],
  Write: ['edit'],
  WebFetch: ['webfetch'],
};

// Parse our own simple frontmatter: `key: value` lines between the first two
// `---` lines. Returns { name, description, tools[], body, eol } where body is
// every byte after the closing `---` line and eol the source's line ending (the
// generated frontmatter uses it, so a CRLF checkout gives no mixed endings).
function parseAgent(text, label = 'agent') {
  const match = /^---\r?\n([\s\S]*?)\r?\n---\r?\n/.exec(text);
  if (!match) throw new Error(`${label}: no frontmatter`);
  const fields = {};
  for (const line of match[1].split(/\r?\n/)) {
    const kv = /^([A-Za-z][\w-]*):\s*(.*)$/.exec(line);
    if (kv) fields[kv[1]] = kv[2].trim();
  }
  if (!fields.name) throw new Error(`${label}: frontmatter has no name`);
  if (!fields.description) throw new Error(`${label}: frontmatter has no description`);
  const tools = (fields.tools || '')
    .split(',')
    .map((t) => t.trim())
    .filter(Boolean);
  return {
    name: fields.name,
    description: fields.description,
    tools,
    body: text.slice(match[0].length),
    eol: match[0].includes('\r\n') ? '\r\n' : '\n',
  };
}

// Map the agent's Claude tools through `table`; an unmapped tool throws so a new
// Claude tool in agents/ is added to the map rather than dropped silently.
function mapTools(agent, table, cli) {
  const out = [];
  for (const tool of agent.tools) {
    if (!Object.prototype.hasOwnProperty.call(table, tool)) {
      throw new Error(
        `agent ${agent.name}: tool "${tool}" has no ${cli} mapping (add it to lib/convertAgents.js)`,
      );
    }
    for (const mapped of table[tool]) {
      const name = mapped.toLowerCase();
      if (!out.includes(name)) out.push(name);
    }
  }
  return out;
}

function markerLine(agent) {
  return `${GENERATED_MARKER}${agent.name}.md. Edit the source, then re-run update.`;
}

function render(agent, lines) {
  const eol = agent.eol || '\n';
  return `${lines.join(eol)}${eol}${agent.body}`;
}

// omp: `name` and `description` required; `tools` a comma list; `blocking: true`
// so `omp -p` does not cancel the subagent at exit. No `model`: it inherits.
function toOmp(agent) {
  const tools = mapTools(agent, OMP_TOOLS, 'omp');
  const lines = [
    '---',
    markerLine(agent),
    `name: ${agent.name}`,
    `description: ${JSON.stringify(agent.description)}`,
  ];
  if (tools.length) lines.push(`tools: ${tools.join(', ')}`);
  lines.push('blocking: true', '---');
  return render(agent, lines);
}

// OpenCode: identity is the file name; `mode: subagent` so it can run as one;
// `permission` is ordered and the last match wins, so `"*": deny` goes first and
// the agent's tools are re-allowed after it. No `model`: it inherits.
function toOpencode(agent) {
  const perms = mapTools(agent, OPENCODE_PERMISSIONS, 'OpenCode');
  const lines = [
    '---',
    markerLine(agent),
    `description: ${JSON.stringify(agent.description)}`,
    'mode: subagent',
    'permission:',
    '  "*": deny',
    ...perms.map((p) => `  ${p}: allow`),
    '---',
  ];
  return render(agent, lines);
}

module.exports = {
  GENERATED_MARKER,
  OMP_TOOLS,
  OPENCODE_PERMISSIONS,
  parseAgent,
  toOmp,
  toOpencode,
};
